// Runtime translation for the TUI.
// TUI 运行时文案翻译。
//
// Catalogs are generated by `vulcan-tui-i18n sync` from the WebUI catalogs and embedded at compile
// time. Lookup semantics mirror the WebUI: a key missing in the active locale falls back to the
// default locale, and `{name}` placeholders without a value are left untouched.
// 目录由 `vulcan-tui-i18n sync` 从 WebUI 目录生成并在编译期内嵌。查找语义与 WebUI 一致：
// 当前语言缺失的键回退到默认语言，没有取值的 `{name}` 占位符保持原样。

mod generated_catalogs;

use std::collections::HashMap;
use std::sync::{OnceLock, RwLock};

pub use generated_catalogs::{DEFAULT_LOCALE, LOCALES};

/// One embedded locale produced by the sync tool.
/// 同步工具生成的一种内嵌语言。
#[derive(Debug)]
pub struct GeneratedLocale {
    pub code: &'static str,
    pub native_name: &'static str,
    pub mark: &'static str,
    pub messages_json: &'static str,
}

struct Catalogs {
    active: &'static str,
    active_messages: HashMap<String, String>,
    default_messages: HashMap<String, String>,
}

static CATALOGS: OnceLock<RwLock<Catalogs>> = OnceLock::new();

fn catalogs() -> &'static RwLock<Catalogs> {
    CATALOGS.get_or_init(|| {
        let default_messages = parse_locale(DEFAULT_LOCALE);
        RwLock::new(Catalogs {
            active: DEFAULT_LOCALE,
            active_messages: default_messages.clone(),
            default_messages,
        })
    })
}

fn parse_locale(code: &str) -> HashMap<String, String> {
    LOCALES
        .iter()
        .find(|locale| locale.code == code)
        .map(|locale| {
            serde_json::from_str(locale.messages_json)
                .unwrap_or_else(|error| panic!("generated catalog {code} is invalid: {error}"))
        })
        .unwrap_or_default()
}

/// Switches the active locale; unknown codes are rejected and leave the current locale in place.
/// 切换当前语言；未知代码被拒绝并保持当前语言不变。
pub fn set_active_locale(code: &str) -> bool {
    let Some(locale) = LOCALES.iter().find(|locale| locale.code == code) else {
        return false;
    };
    let messages = parse_locale(locale.code);
    let mut guard = catalogs().write().expect("i18n lock poisoned");
    guard.active = locale.code;
    guard.active_messages = messages;
    true
}

/// Returns the active locale code.
/// 返回当前语言代码。
pub fn active_locale() -> &'static str {
    catalogs().read().expect("i18n lock poisoned").active
}

/// Looks up one key with default-locale fallback; unknown keys render as the key itself.
/// 按默认语言回退查找一个键；未知键渲染为键本身。
pub fn text(key: &str) -> String {
    let guard = catalogs().read().expect("i18n lock poisoned");
    guard
        .active_messages
        .get(key)
        .or_else(|| guard.default_messages.get(key))
        .cloned()
        .unwrap_or_else(|| key.to_string())
}

/// Looks up one key and replaces `{name}` placeholders with the given values.
/// 查找一个键并用给定值替换 `{name}` 占位符。
pub fn format(key: &str, values: &[(&str, String)]) -> String {
    let template = text(key);
    let mut out = String::with_capacity(template.len());
    let mut rest = template.as_str();
    while let Some(open) = rest.find('{') {
        out.push_str(&rest[..open]);
        let after = &rest[open + 1..];
        let close = after.find('}');
        let name = close.map(|end| &after[..end]);
        match name.and_then(|name| {
            let valid = !name.is_empty() && name.chars().all(|c| c.is_alphanumeric() || c == '_');
            valid
                .then(|| values.iter().find(|(k, _)| *k == name))
                .flatten()
        }) {
            Some((_, value)) => {
                out.push_str(value);
                rest = &after[close.unwrap_or(0) + 1..];
            }
            None => {
                out.push('{');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

/// Maps a BCP 47 tag to a supported locale.
/// 将 BCP 47 标签映射到受支持的语言。
///
/// Port of `matchLocaleTag` in `apps/vulcan-code-web/src/i18n-locales.ts`; keep in sync when the
/// upstream rule changes. Chinese resolves by script (`Hant`/`Hans`) first, then by region;
/// Traditional HK uses the Hong Kong catalog while TW and MO use Taiwan.
/// 移植自 `apps/vulcan-code-web/src/i18n-locales.ts` 的 `matchLocaleTag`；上游规则变化时同步更新。
/// 中文先按书写系统（`Hant`/`Hans`）再按地区解析；香港繁体使用香港目录，台湾与澳门使用台湾目录。
pub fn match_locale_tag(tag: &str) -> Option<&'static str> {
    let normalized = tag.trim().replace('_', "-").to_lowercase();
    let subtags: Vec<&str> = normalized.split('-').filter(|s| !s.is_empty()).collect();
    let language = *subtags.first()?;
    let has = |code: &str| LOCALES.iter().find(|l| l.code == code).map(|l| l.code);
    if language == "zh" {
        let traditional_locale = if subtags.contains(&"hk") {
            "zh-HK"
        } else {
            "zh-TW"
        };
        if subtags.contains(&"hant") {
            return has(traditional_locale);
        }
        if subtags.contains(&"hans") {
            return has("zh-CN");
        }
        let traditional = subtags.iter().any(|s| matches!(*s, "tw" | "hk" | "mo"));
        return has(if traditional {
            traditional_locale
        } else {
            "zh-CN"
        });
    }
    let joined = subtags.join("-");
    LOCALES
        .iter()
        .find(|l| l.code.to_lowercase() == joined)
        .or_else(|| {
            LOCALES
                .iter()
                .find(|l| l.code.split('-').next().unwrap_or_default().to_lowercase() == language)
        })
        .map(|l| l.code)
}

/// Resolves the startup locale: explicit flag, then service `uiLocale`, then the OS, then default.
/// 解析启动语言：显式参数优先，其次服务 `uiLocale`，再次操作系统，最后默认语言。
///
/// The TUI never persists the result.
/// TUI 从不持久化该结果。
pub fn resolve_locale(explicit: Option<&str>, service_locale: Option<&str>) -> &'static str {
    let exact = |code: &str| LOCALES.iter().find(|l| l.code == code).map(|l| l.code);
    explicit
        .and_then(|code| exact(code).or_else(|| match_locale_tag(code)))
        .or_else(|| service_locale.and_then(exact))
        .or_else(|| sys_locale::get_locales().find_map(|tag| match_locale_tag(&tag)))
        .unwrap_or(DEFAULT_LOCALE)
}

/// Translates a synced key: `tr!("key")` or `tr!("key", name = value, ...)`.
/// 翻译一个已同步的键：`tr!("key")` 或 `tr!("key", name = value, ...)`。
///
/// Keys must be string literals so `vulcan-tui-i18n sync` can discover them.
/// 键必须是字符串字面量，以便 `vulcan-tui-i18n sync` 发现它们。
#[macro_export]
macro_rules! tr {
    ($key:literal $(,)?) => {
        $crate::i18n::text($key)
    };
    ($key:literal, $($name:ident = $value:expr),+ $(,)?) => {
        $crate::i18n::format($key, &[$((stringify!($name), ($value).to_string())),+])
    };
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn locale_matching_follows_webui_rules() {
        assert_eq!(match_locale_tag("zh-Hant-HK"), Some("zh-HK"));
        assert_eq!(match_locale_tag("zh_HK"), Some("zh-HK"));
        assert_eq!(match_locale_tag("zh-MO"), Some("zh-TW"));
        assert_eq!(match_locale_tag("zh"), Some("zh-CN"));
        assert_eq!(match_locale_tag("pt-PT"), Some("pt-BR"));
        assert_eq!(match_locale_tag("EN"), Some("en-US"));
        assert_eq!(match_locale_tag("xx"), None);
    }

    #[test]
    fn format_replaces_known_placeholders_and_keeps_unknown() {
        let out = format("tui.test.missing {x}", &[]);
        assert_eq!(out, "tui.test.missing {x}");
    }

    /// Source scanner shared with the `vulcan-tui-i18n` binary.
    /// 与 `vulcan-tui-i18n` 二进制共用的源码扫描器。
    #[path = "../../i18n_sync/scan.rs"]
    mod scan;

    #[test]
    fn every_used_key_resolves_in_default_catalog() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        let src = root.join("src");
        let used = scan::used_keys(&src, &[src.join("i18n_sync")]).unwrap();
        let default: HashMap<String, String> = parse_locale(DEFAULT_LOCALE);
        let missing: Vec<_> = used.iter().filter(|k| !default.contains_key(*k)).collect();
        assert!(
            missing.is_empty(),
            "run `cargo run --bin vulcan-tui-i18n -- sync`; keys missing from the generated \
             default catalog: {missing:?}"
        );
    }
}
